css:
.ap-art{position:relative;overflow:hidden}.ap-art svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.fx-sp{width:min(1060px,100%);display:grid;gap:1.6em}
.fx-sp .top{display:flex;justify-content:space-between;align-items:end;gap:1em;flex-wrap:wrap}
.fx-sp h2{font-size:clamp(1.8em,4vw,2.6em)}.fx-sp .top p{opacity:.6;font-size:.95em;max-width:30em}
.fx-sp .grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(1em,3vw,2em)}
.fx-sp figure{margin:0;display:grid;gap:.6em}
.fx-sp figcaption{display:grid;gap:.1em}.fx-sp figcaption b{font:600 1em var(--font-heading)}.fx-sp figcaption span{font-size:.85em;opacity:.65}
.sp{--p:1;position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;isolation:isolate;container-type:inline-size}
.sp-strips{position:absolute;inset:0;display:flex}
.sp-s{--d:1;--t:clamp(0,calc(var(--p)*1.8 - var(--i)*.1),1);position:relative;flex:none;overflow:hidden;margin-right:-1.5px;width:calc(12.5cqw + 1.5px);transform:translateY(calc((1 - var(--t))*var(--d)*105%))}
.sp-s:nth-child(even){--d:-1}
.sp-in{position:absolute;top:0;height:100%;width:100cqw;left:calc(var(--i)*-12.5cqw)}
.sp-in svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.sp-on>.ap-art{display:none}
@media(max-width:700px){.fx-sp .grid{grid-template-columns:minmax(0,1fr)}.sp{aspect-ratio:1/1}}

js:
(function(){
var els=[].slice.call(document.querySelectorAll('.fx-sp [data-sp]')),N=8;
if(!els.length||(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches))return;
function uid(s,n){return s.replace(/id="(ap-[a-z0-9]+)"/g,'id="$1-'+n+'"').replace(/url\(#(ap-[a-z0-9]+)\)/g,'url(#$1-'+n+')')}
var uidn=0;
els.forEach(function(el){var art=el.querySelector('.ap-art'),svg=art.innerHTML,w=document.createElement('div');w.className='sp-strips';w.setAttribute('aria-hidden','true');
 for(var i=0;i<N;i++){var s=document.createElement('div');s.className='sp-s';s.style.setProperty('--i',i);
  var n=document.createElement('div');n.className='sp-in';n.innerHTML=uid(svg,++uidn);s.appendChild(n);w.appendChild(s)}
 el.appendChild(w);el.classList.add('sp-on');art.setAttribute('aria-hidden','true');el.setAttribute('role','img');el.setAttribute('aria-label',art.getAttribute('aria-label')||'')});
var raf=0;
function cl(v){return v<0?0:v>1?1:v}
function upd(){raf=0;var vh=window.innerHeight||800;
 els.forEach(function(el){var r=el.getBoundingClientRect(),p=cl((vh*.96-r.top)/(vh*.75)),e=p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2;el.style.setProperty('--p',e.toFixed(3))})}
function req(){if(!raf)raf=requestAnimationFrame(upd)}
addEventListener('scroll',req,{passive:true});addEventListener('resize',req);upd();
})();
